   756  static int default_ports_tree_node_t_cmp(const void *a, const void *b) {
   757    default_ports_tree_node_t *fa = (default_ports_tree_node_t *) a;
   758    default_ports_tree_node_t *fb = (default_ports_tree_node_t *) b;
   759
   760    //printf("[NDPI] %s(%d, %d)\n", __FUNCTION__, fa->default_port, fb->default_port);
   761
   762    return((fa->default_port == fb->default_port) ? 0 : ((fa->default_port < fb->default_port) ? -1 : 1));
   763  }
